problems.starterCode:
type Delivery = { status: string; trackingId: string; estimatedDays?: number; deliveredAt?: string };

export function summarizeDelivery(delivery: Delivery): string {
  return delivery.status;
}

problems.solutionCode:
type Delivery =
  | { status: 'in_transit'; trackingId: string; estimatedDays: number }
  | { status: 'delivered'; trackingId: string; deliveredAt: string }
  | { status: 'exception'; trackingId: string; reason: string };

function assertNever(value: never): never {
  throw new Error(`Unhandled delivery status: ${JSON.stringify(value)}`);
}

export function summarizeDelivery(delivery: Delivery): string {
  switch (delivery.status) {
    case 'in_transit':
      return `${delivery.trackingId} arrives in ${delivery.estimatedDays} days`;
    case 'delivered':
      return `${delivery.trackingId} delivered at ${delivery.deliveredAt}`;
    case 'exception':
      return `${delivery.trackingId} needs attention: ${delivery.reason}`;
    default:
      return assertNever(delivery);
  }
}

problems.trapMutant:
type Delivery = { status: string; trackingId: string; estimatedDays?: number; deliveredAt?: string; reason?: string };

export function summarizeDelivery(delivery: Delivery): string {
  if (delivery.estimatedDays !== undefined) return `${delivery.trackingId} arrives in ${delivery.estimatedDays} days`;
  if (delivery.deliveredAt !== undefined) return `${delivery.trackingId} delivered at ${delivery.deliveredAt}`;
  return `${delivery.trackingId}: needs attention`;
}

problems.starterCode:
type Adjustment = { kind: string; amount?: number; percent?: number };

export function adjustmentAmount(adjustment: Adjustment, subtotal: number): number {
  if (adjustment.amount) {
    return adjustment.amount;
  }
  return subtotal * (adjustment.percent ?? 1);
}

problems.solutionCode:
type Adjustment = { kind: 'credit'; amount: number } | { kind: 'rate'; percent: number };

export function adjustmentAmount(adjustment: Adjustment, subtotal: number): number {
  switch (adjustment.kind) {
    case 'credit':
      return adjustment.amount;
    case 'rate':
      return subtotal * adjustment.percent / 100;
    default:
      return assertNever(adjustment);
  }
}

function assertNever(value: never): never {
  throw new Error(`Unhandled adjustment: ${JSON.stringify(value)}`);
}

