problems.starterCode:
type Activity =
  | { kind: 'reply'; author: string; body: string }
  | { kind: 'internal_note'; author: string; note: string };
type ActivityFeed = Activity[] | { kind: 'reply'; author: string; body: string }[] | { kind: 'internal_note'; author: string; note: string }[];

export function renderActivityFeed(feed: ActivityFeed): string[] {
  return feed.filter((activity) => activity.kind === 'reply').map((activity) => {
    if (activity.kind === 'reply') {
      return `${activity.author}: ${activity.body}`;
    }
    return `${activity.author || 'Staff'}: ${activity.note}`;
  });
}

